using System;
using Framework.Grid;
using UnityEngine;

namespace Framework.AI.Perception
{
    /// <summary>
    /// グリッド上の2点間における視線の遮断を判定する。
    /// </summary>
    /// <remarks>
    /// セル中心間の直線を対象とする。
    /// セルの角を通過する場合は隣接する両側のセルも検査する。
    /// </remarks>
    public static class GridLineOfSight
    {
        /// <summary>
        /// 指定された2点間の視線が通っているか判定する。
        /// </summary>
        /// <typeparam name="T">グリッドのセルデータ型</typeparam>
        /// <param name="map">判定対象のグリッド</param>
        /// <param name="origin">視線の始点。グリッド座標</param>
        /// <param name="target">視線の終点。グリッド座標</param>
        /// <param name="blocksSight">
        /// 指定セルが視線を遮る場合にtrueを返す判定処理。
        /// </param>
        /// <returns>
        /// 視線が通っている場合はtrue。
        /// 範囲外または遮蔽物がある場合はfalse。
        /// </returns>
        /// <remarks>
        /// 始点セルは遮蔽判定から除外する。
        /// 終点セルは遮蔽判定に含める。
        /// 判定中にグリッドを変更しないこと。
        /// </remarks>
        /// <exception cref="ArgumentNullException">
        /// グリッドまたは判定処理がnullの場合に発生する。
        /// </exception>
        public static bool HasLineOfSight<T>(
            GridMap<T> map,
            Vector2Int origin,
            Vector2Int target,
            Func<Vector2Int, bool> blocksSight)
        {
            if (map == null)
            {
                throw new ArgumentNullException(nameof(map));
            }

            if (blocksSight == null)
            {
                throw new ArgumentNullException(
                    nameof(blocksSight));
            }

            if (!map.IsInside(origin) ||
                !map.IsInside(target))
            {
                return false;
            }

            if (origin == target)
            {
                return true;
            }

            // 各軸における移動距離。
            int distanceX = Math.Abs(target.x - origin.x);
            int distanceY = Math.Abs(target.y - origin.y);

            // 各軸における走査方向。
            int stepX = Math.Sign(target.x - origin.x);
            int stepY = Math.Sign(target.y - origin.y);

            // 現在走査しているセル。
            int x = origin.x;
            int y = origin.y;

            // 各軸における走査済みの移動量。
            int traversedX = 0;
            int traversedY = 0;

            while (traversedX < distanceX ||
                   traversedY < distanceY)
            {
                // 次に通過するセル境界を比較する。
                // 浮動小数点による角判定の誤差を避ける。
                long boundaryX =
                    (1L + 2L * traversedX) * distanceY;

                long boundaryY =
                    (1L + 2L * traversedY) * distanceX;

                if (boundaryX == boundaryY)
                {
                    // セルの角を通過する場合は、
                    // 両側の隣接セルも遮蔽判定する。
                    var horizontal =
                        new Vector2Int(x + stepX, y);

                    var vertical =
                        new Vector2Int(x, y + stepY);

                    if (IsBlocked(
                            map, horizontal, blocksSight) ||
                        IsBlocked(
                            map, vertical, blocksSight))
                    {
                        return false;
                    }

                    x += stepX;
                    y += stepY;

                    traversedX++;
                    traversedY++;
                }
                else if (boundaryX < boundaryY)
                {
                    x += stepX;
                    traversedX++;
                }
                else
                {
                    y += stepY;
                    traversedY++;
                }

                // 移動先のセルによる遮蔽を確認する。
                var position = new Vector2Int(x, y);

                if (IsBlocked(map, position, blocksSight))
                {
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 指定セルが視線を遮るか判定する。
        /// </summary>
        /// <typeparam name="T">セルデータ型</typeparam>
        /// <param name="map">判定対象のグリッド</param>
        /// <param name="position">判定位置</param>
        /// <param name="blocksSight">遮蔽判定処理</param>
        /// <returns>範囲外または遮蔽物の場合はtrue</returns>
        private static bool IsBlocked<T>(
            GridMap<T> map,
            Vector2Int position,
            Func<Vector2Int, bool> blocksSight)
        {
            return !map.IsInside(position) ||
                   blocksSight(position);
        }
    }
}
